#include <vector>
#include <unordered_set>
#include <algorithm>
#include <numeric>

class Solution {
public:
    long long maxDistinctSum(std::vector<int>& nums, int k) {
        std::unordered_set<int> uniq;
        for (int x : nums) {
            if (x > 0) uniq.insert(x);
        }
        std::vector<int> pos(uniq.begin(), uniq.end());
        std::sort(pos.begin(), pos.end(), std::greater<int>());

        long long total = 0;
        int take = std::min((int)pos.size(), k);
        for (int i = 0; i < take; ++i) {
            total += pos[i];
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long maxDistinctSum(int[] nums, int k) {
        Set<Integer> uniq = new HashSet<>();
        for (int x : nums) {
            if (x > 0) uniq.add(x);
        }
        List<Integer> pos = new ArrayList<>(uniq);
        pos.sort(Collections.reverseOrder());

        long total = 0;
        int take = Math.min(pos.size(), k);
        for (int i = 0; i < take; i++) {
            total += pos.get(i);
        }
        return total;
    }
}

var maxDistinctSum = function(nums, k) {
    const uniq = Array.from(new Set(nums)).filter(x => x > 0).sort((a, b) => b - a);
    let total = 0;
    const take = Math.min(uniq.length, k);
    for (let i = 0; i < take; i++) {
        total += uniq[i];
    }
    return total;
};
